property baud_clk_update;
    integer baud_freq_val = `D_BAUD_FREQ;
    integer baud_limit_val = `D_BAUD_LIMIT;
    integer expected_period = (baud_limit_val + baud_freq_val - 1) / baud_freq_val;
    @(posedge clock) disable iff (reset)
    $fell(reset) |=> (baud_clk == 0) [*expected_period] ##1 $rose(baud_clk);
endproperty

assert property (baud_clk_update);
```

