```systemverilog
function integer compute_baud_freq(input integer global_clock_freq, input integer baud_rate);
   // Implementation of baud frequency calculation (as described in the baud_gen module)
   integer gcd_val;
   gcd_val = gcd(global_clock_freq, 16 * baud_rate);
   return (16 * baud_rate / gcd_val);
endfunction

assert property (@(posedge clock)
   $rose(reset) |=> (baud_freq == compute_baud_freq(global_clock_freq, baud_rate))
);
```

